/**
 * DragLine — 拖拽时的「水流」连接线。
 *
 * 视觉：白色半透明、像水在流（用户要求），四层叠加：
 *   1. 光晕   宽描边 + 高斯模糊 + 极低透明 → 水汽感
 *   2. 主线   沿线渐变（两端淡出）的半透明主体
 *   3. 流带   短划线沿路径滑动 → 「在流」而不是「虚线在抖」
 *   4. 水珠   9 颗不同大小/速度/透明度的粒子顺流而下
 *
 * 颜色取 CSS 变量 --ccr-flow-color（默认映射到 DSH 主题 token，
 * 深色主题下即白色；纯白在浅色主题会消失，所以不写死）。
 *
 * 时序：dragging → (松手) → shrinking(200ms) → pulsing(300ms) → onComplete
 */
import { useState, useEffect, useRef, useMemo } from 'react'

interface Point { x: number; y: number }

interface DragLineProps {
  start: Point
  end: Point
  /** 松手后置 true，触发退出动效。 */
  releasing?: boolean
  /** 退出动效结束（父组件据此卸载）。 */
  onComplete?: () => void
}

interface ParticleProfile {
  /** 起始相位 0..1 */
  offset: number
  /** 半径 px */
  size: number
  /** 速度倍率 */
  speed: number
  /** 基础透明度 */
  opacity: number
}

const FLOW_COLOR = 'var(--ccr-flow-color, #ffffff)'
const BASE_SPEED = 300 // px/s
const WATER_BASE_MS = 200
const WATER_PULSE_MS = 300

/** 9 颗水珠的确定性参数（不用随机，避免每帧抖动）。 */
const PARTICLE_PROFILES: ParticleProfile[] = Array.from({ length: 9 }, (_, i) => ({
  offset: i / 9,
  size: 0.7 + (((i * 37) % 100) / 100) * 1.6,      // 0.7 – 2.3
  speed: 0.72 + (((i * 53) % 100) / 100) * 0.7,    // 0.72 – 1.42
  opacity: 0.3 + (((i * 71) % 100) / 100) * 0.6,   // 0.3 – 0.9
}))

/** 唯一 id：同一时刻只应有一个 DragLine，但用计数器更稳。 */
let gradientSeq = 0

function buildBezierPath(start: Point, end: Point): string {
  const dx = end.x - start.x
  const dy = end.y - start.y
  // 控制点沿法线方向偏移，形成柔和弧线（比固定 -20 更自然）
  const nx = -dy
  const ny = dx
  const len = Math.hypot(nx, ny) || 1
  const bulge = Math.min(60, len * 0.22)
  const cx = (start.x + end.x) / 2 + (nx / len) * bulge
  const cy = (start.y + end.y) / 2 + (ny / len) * bulge
  return `M ${start.x} ${start.y} Q ${cx} ${cy} ${end.x} ${end.y}`
}

export function DragLine({ start, end, releasing = false, onComplete }: DragLineProps) {
  const [phase, setPhase] = useState<'dragging' | 'shrinking' | 'pulsing'>('dragging')
  const [particles, setParticles] = useState<{ t: number }[]>([])
  const pathRef = useRef<SVGPathElement>(null)
  const rafRef = useRef<number>(0)
  const gradId = useMemo(() => `ccr-flow-grad-${++gradientSeq}`, [])
  const blurId = useMemo(() => `ccr-flow-blur-${gradientSeq}`, [gradientSeq])

  const path = useMemo(() => buildBezierPath(start, end), [start, end])

  // 松手 → 进入退出动效
  useEffect(() => {
    if (releasing && phase === 'dragging') {
      cancelAnimationFrame(rafRef.current)
      setPhase('shrinking')
    }
  }, [releasing, phase])

  // 水珠流动
  useEffect(() => {
    if (phase !== 'dragging') return
    const pathEl = pathRef.current
    if (!pathEl) return

    let totalLength = 0
    try {
      totalLength = pathEl.getTotalLength()
    } catch {
      return
    }
    if (!Number.isFinite(totalLength) || totalLength <= 0) return

    setParticles(PARTICLE_PROFILES.map((p) => ({ t: p.offset * totalLength })))

    let last = performance.now()
    const tick = (now: number) => {
      const dt = Math.min((now - last) / 1000, 0.1) // 夹住后台切回的巨帧
      last = now
      setParticles((prev) =>
        prev.map((p, i) => ({
          t: (p.t + BASE_SPEED * PARTICLE_PROFILES[i].speed * dt) % totalLength,
        })),
      )
      rafRef.current = requestAnimationFrame(tick)
    }
    rafRef.current = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(rafRef.current)
  }, [phase, path])

  // 退出动效时序
  useEffect(() => {
    if (phase === 'shrinking') {
      const timer = setTimeout(() => setPhase('pulsing'), WATER_BASE_MS)
      return () => clearTimeout(timer)
    }
    if (phase === 'pulsing') {
      const timer = setTimeout(() => onComplete?.(), WATER_PULSE_MS)
      return () => clearTimeout(timer)
    }
    return undefined
  }, [phase, onComplete])

  const pulsing = phase === 'pulsing'
  const coreStyle: React.CSSProperties = {
    stroke: `url(#${gradId})`,
    strokeWidth: pulsing ? 3.5 : 2,
    strokeOpacity: pulsing ? 0.3 : 0.9,
    transition: 'stroke-width 200ms ease, stroke-opacity 200ms ease',
  }

  return (
    <svg
      className="ccr-drag-line"
      aria-hidden="true"
      style={{
        position: 'fixed',
        // ⚠️ 绝不要用 100vw/100vh：vw 含纵向滚动条宽度，页面一有滚动条就撑出
        // 横向滚动条 → 整个布局被挤动 → 观感就是"输入框会跑"。
        // 用四边 inset 贴齐，尺寸自动等于视口内容区（不含滚动条）。
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        pointerEvents: 'none', // 内联兜底：绝不能挡住交互
        zIndex: 9999,
        overflow: 'visible',
      }}
    >
      <defs>
        {/* 沿线渐变：两端淡出，中间最亮 —— 这是「水」而不是「线」的关键 */}
        <linearGradient
          id={gradId}
          gradientUnits="userSpaceOnUse"
          x1={start.x}
          y1={start.y}
          x2={end.x}
          y2={end.y}
        >
          <stop offset="0%" stopColor={FLOW_COLOR} stopOpacity="0" />
          <stop offset="18%" stopColor={FLOW_COLOR} stopOpacity="0.55" />
          <stop offset="50%" stopColor={FLOW_COLOR} stopOpacity="0.95" />
          <stop offset="82%" stopColor={FLOW_COLOR} stopOpacity="0.55" />
          <stop offset="100%" stopColor={FLOW_COLOR} stopOpacity="0" />
        </linearGradient>
        <filter id={blurId} x="-30%" y="-30%" width="160%" height="160%">
          <feGaussianBlur stdDeviation="3" />
        </filter>
      </defs>

      {/* 1. 光晕（水汽） */}
      <path d={path} className="ccr-flow__glow" filter={`url(#${blurId})`} />

      {/* 2. 主线（渐变白，两端淡出） */}
      <path ref={pathRef} d={path} className="ccr-flow__core" style={coreStyle} />

      {/* 3. 流带（沿路径滑动，制造「流动」） */}
      {!pulsing && <path d={path} className="ccr-flow__band" />}

      {/* 4. 水珠 */}
      {!pulsing &&
        phase === 'dragging' &&
        particles.map((p, i) => {
          const pathEl = pathRef.current
          if (!pathEl) return null
          const profile = PARTICLE_PROFILES[i]
          let point: { x: number; y: number }
          try {
            point = pathEl.getPointAtLength(p.t)
          } catch {
            return null
          }
          const total = pathEl.getTotalLength() || 1
          const progress = p.t / total
          // 两端淡出，避免水珠在端点突然出现/消失
          const edgeFade = Math.sin(progress * Math.PI)
          return (
            <circle
              key={i}
              className="ccr-flow__particle"
              cx={point.x}
              cy={point.y}
              r={profile.size}
              opacity={profile.opacity * edgeFade}
              style={{ filter: 'blur(0.6px)' }}
            />
          )
        })}
    </svg>
  )
}
